		{"sub-agent in whole dollars", agentRow{Agent: sub, cost: priced(1234.5)}, "\u2265 ~$1235"},
		{"widest two-decimal sub-agent", agentRow{Agent: sub, cost: priced(999.99)}, "\u2265 ~$999.99"},
