		{"unpriced sub-agent", agentRow{Agent: sub, cost: pricing.Estimate{Status: pricing.Unpriced}}, "-"},
		{"no tokens", agentRow{Agent: sub, cost: pricing.Estimate{Status: pricing.NoTokens}}, "-"},
